"use client";

import { useState, useEffect, useCallback, useRef, forwardRef, useImperativeHandle } from "react";
import { motion, AnimatePresence } from "framer-motion";

interface TypingTextProps {
  /** 한 글자씩 표시할 원본 문자열입니다. */
  text: string;
  speed?: number; // 타이핑 속도 (밀리초)
  delay?: number; // 시작 지연 시간 (밀리초)
  /** 타이핑 텍스트와 커서를 감싸는 컨테이너에 추가할 CSS 클래스입니다. */
  className?: string;
  onComplete?: () => void; // 타이핑 완료 시 콜백
  showCursor?: boolean; // 커서 표시 여부
  cursorChar?: string; // 커서 문자
  loop?: boolean; // 반복 여부
  pauseTime?: number; // 반복 시 일시정지 시간
  cursorClassName?: string; // 커서 스타일 커스터마이징
  textClassName?: string; // 텍스트 스타일 커스터마이징
  autoStart?: boolean; // 자동 시작 여부
  onStart?: () => void; // 타이핑 시작 시 콜백
  onPause?: () => void; // 일시정지 시 콜백
  onResume?: () => void; // 재개 시 콜백
}

// 외부에서 제어할 수 있는 메서드들을 위한 타입
export interface TypingTextRef {
  start: () => void;
  pause: () => void;
  resume: () => void;
  restart: () => void;
}

const TypingText = forwardRef<TypingTextRef, TypingTextProps>(
  (
    {
      text,
      speed = 100,
      delay = 0,
      className = "",
      onComplete,
      showCursor = true,
      cursorChar = "|",
      loop = false,
      pauseTime = 1000,
      cursorClassName = "",
      textClassName = "",
      autoStart = true,
      onStart,
      onPause,
      onResume,
    },
    ref,
  ) => {
    const [displayText, setDisplayText] = useState("");
    const [currentIndex, setCurrentIndex] = useState(0);
    const [isTyping, setIsTyping] = useState(false);
    const [isPaused, setIsPaused] = useState(false);
    const timeoutRefs = useRef<NodeJS.Timeout[]>([]);

    // 타이머 정리 함수
    const clearAllTimeouts = useCallback(() => {
      timeoutRefs.current.forEach(clearTimeout);
      timeoutRefs.current = [];
    }, []);

    // 타이핑 시작
    const startTyping = useCallback(() => {
      setIsTyping(true);
      setIsPaused(false);
      setCurrentIndex(0);
      setDisplayText("");
      onStart?.();
    }, [onStart]);

    // 타이핑 일시정지
    const pauseTyping = useCallback(() => {
      setIsPaused(true);
      clearAllTimeouts();
      onPause?.();
    }, [clearAllTimeouts, onPause]);

    // 타이핑 재개
    const resumeTyping = useCallback(() => {
      if (isPaused && currentIndex < text.length) {
        setIsPaused(false);
        setIsTyping(true);
        onResume?.();
      }
    }, [isPaused, currentIndex, text.length, onResume]);

    // 타이핑 재시작
    const restartTyping = useCallback(() => {
      clearAllTimeouts();
      startTyping();
    }, [clearAllTimeouts, startTyping]);

    // 외부에서 제어할 수 있는 메서드들 노출
    useImperativeHandle(
      ref,
      () => ({
        start: startTyping,
        pause: pauseTyping,
        resume: resumeTyping,
        restart: restartTyping,
      }),
      [startTyping, pauseTyping, resumeTyping, restartTyping],
    );

    // 자동 시작 처리
    useEffect(() => {
      if (!autoStart) return;

      const startTypingWithDelay = () => {
        if (delay > 0) {
          const delayTimer = setTimeout(startTyping, delay);
          timeoutRefs.current.push(delayTimer);
        } else {
          startTyping();
        }
      };

      startTypingWithDelay();

      return clearAllTimeouts;
    }, [delay, text, autoStart, startTyping, clearAllTimeouts]);

    // 타이핑 로직
    useEffect(() => {
      if (!isTyping || isPaused || currentIndex >= text.length) {
        if (currentIndex >= text.length) {
          setIsTyping(false);
          onComplete?.();

          if (loop) {
            const loopTimer = setTimeout(() => {
              setCurrentIndex(0);
              setDisplayText("");
              setIsTyping(true);
            }, pauseTime);
            timeoutRefs.current.push(loopTimer);
          }
        }
        return;
      }

      const typingTimer = setTimeout(() => {
        setDisplayText(text.slice(0, currentIndex + 1));
        setCurrentIndex((prev) => prev + 1);
      }, speed);

      timeoutRefs.current.push(typingTimer);

      return () => {
        clearTimeout(typingTimer);
        timeoutRefs.current = timeoutRefs.current.filter((timer) => timer !== typingTimer);
      };
    }, [currentIndex, isTyping, isPaused, text, speed, onComplete, loop, pauseTime]);

    // 컴포넌트 언마운트 시 정리
    useEffect(() => {
      return clearAllTimeouts;
    }, [clearAllTimeouts]);

    return (
      <motion.div
        className={`inline-block ${className}`}
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.3 }}
      >
        <span className={`font-mono ${textClassName}`}>
          {displayText}
          <AnimatePresence>
            {showCursor && (
              <motion.span
                className={`inline-block ${cursorClassName}`}
                initial={{ opacity: 1 }}
                animate={{
                  opacity: [1, 0, 1],
                }}
                transition={{
                  duration: 1,
                  repeat: Infinity,
                  ease: "linear",
                }}
              >
                {cursorChar}
              </motion.span>
            )}
          </AnimatePresence>
        </span>
      </motion.div>
    );
  },
);

TypingText.displayName = "TypingText";

export default TypingText;

"use client";

import { useState, useEffect, useRef } from "react";

export interface TextScrambleProps {
  /** 무작위 문자가 바뀐 뒤 최종적으로 표시할 문자열입니다. */
  text: string;
  speed?: number; // 스크램블 속도 (밀리초)
  delay?: number; // 시작 지연 시간 (밀리초)
  /** 텍스트 컨테이너에 적용할 글꼴 크기, 굵기 등의 CSS 클래스입니다. */
  className?: string;
  onComplete?: () => void; // 스크램블 완료 시 콜백
  loop?: boolean; // 반복 여부
  pauseTime?: number; // 반복 시 일시정지 시간
  characters?: string; // 스크램블에 사용할 문자셋
  revealSpeed?: number; // 각 문자가 복원되는 속도
  trigger?: "auto" | "hover" | "manual"; // 트리거 방식
  onHover?: () => void; // 호버 시 콜백
}

const TextScramble = ({
  text,
  speed = 50,
  delay = 0,
  className = "",
  onComplete,
  loop = false,
  pauseTime = 1000,
  characters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+-=[]{}|;:,.<>?",
  revealSpeed = 100,
  trigger = "auto",
  onHover,
}: TextScrambleProps) => {
  const [displayText, setDisplayText] = useState("");
  const [isAnimating, setIsAnimating] = useState(false);
  const intervalRef = useRef<NodeJS.Timeout | null>(null);
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);
  const frameRef = useRef(0);

  const getRandomChar = () => {
    return characters[Math.floor(Math.random() * characters.length)];
  };

  const scrambleText = () => {
    if (isAnimating) return;

    setIsAnimating(true);
    frameRef.current = 0;

    const animate = () => {
      const frame = frameRef.current;
      const revealIndex = Math.floor(frame / (revealSpeed / speed));

      let scrambledText = "";

      for (let i = 0; i < text.length; i++) {
        if (i < revealIndex) {
          // 이미 복원된 문자
          scrambledText += text[i];
        } else {
          // 아직 스크램블 중인 문자
          if (text[i] === " ") {
            scrambledText += " ";
          } else {
            scrambledText += getRandomChar();
          }
        }
      }

      setDisplayText(scrambledText);

      if (revealIndex >= text.length) {
        // 애니메이션 완료
        setDisplayText(text);
        setIsAnimating(false);
        onComplete?.();

        if (loop) {
          timeoutRef.current = setTimeout(() => {
            setDisplayText("");
            frameRef.current = 0;
            scrambleText();
          }, pauseTime);
        }
      } else {
        frameRef.current++;
        intervalRef.current = setTimeout(animate, speed);
      }
    };

    animate();
  };

  const handleMouseEnter = () => {
    if (trigger === "hover" && !isAnimating) {
      onHover?.();
      scrambleText();
    }
  };

  useEffect(() => {
    // auto 모드에서만 자동 시작
    if (trigger === "auto") {
      const startTimeout = setTimeout(() => {
        scrambleText();
      }, delay);

      return () => {
        clearTimeout(startTimeout);
        if (intervalRef.current) {
          clearTimeout(intervalRef.current);
        }
        if (timeoutRef.current) {
          clearTimeout(timeoutRef.current);
        }
      };
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [text, speed, delay, loop, pauseTime, characters, revealSpeed, trigger]);

  // text가 변경되면 애니메이션 재시작
  useEffect(() => {
    if (intervalRef.current) {
      clearTimeout(intervalRef.current);
    }
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }
    setDisplayText("");
    setIsAnimating(false);
    frameRef.current = 0;

    const startTimeout = setTimeout(() => {
      scrambleText();
    }, delay);

    return () => {
      clearTimeout(startTimeout);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [text]);

  // hover 모드일 때 초기 텍스트를 표시
  const shouldShowInitialText = trigger === "hover" && !displayText && !isAnimating;

  return (
    <span
      className={`${className} ${trigger === "hover" ? "cursor-pointer select-none" : ""}`}
      onMouseEnter={trigger === "hover" ? handleMouseEnter : undefined}
    >
      {shouldShowInitialText
        ? text
        : displayText ||
          text.split("").map((char, i) => (
            <span key={i} className="opacity-0">
              {char}
            </span>
          ))}
    </span>
  );
};

export default TextScramble;

"use client";
import { useRef, useEffect } from "react";
import { motion, useMotionValue, useSpring } from "framer-motion";

/**
 * MagneticLetters
 * - 텍스트의 각 글자가 마우스 커서에 자석처럼 개별적으로 끌려오는 효과
 * - 마우스가 가까울수록 더 강하게, 멀수록 약하게 끌림
 * - framer-motion 기반, 반응형
 * - 예시: <MagneticLetters text="MAGNETIC TEXT" />
 */
interface MagneticLettersProps {
  /** 마우스에 반응하도록 글자 단위로 나눌 문자열입니다. */
  text: string;
  strength?: number; // 자석 강도 (기본 40)
  threshold?: number; // 영향 범위 배수 (기본 6)
  stiffness?: number; // 스프링 강성 (기본 400)
  damping?: number; // 스프링 댐핑 (기본 30)
  textColor?: string; // 텍스트 색상
  /** 글자들을 감싸는 inline-flex 요소에 추가할 CSS 클래스입니다. */
  className?: string;
  /** 글자들을 감싸는 요소에 적용할 인라인 스타일입니다. */
  style?: React.CSSProperties;
}

interface MagneticLetterProps {
  char: string;
  strength: number;
  threshold: number;
  stiffness: number;
  damping: number;
  textColor: string;
}

function MagneticLetter({ char, strength, threshold, stiffness, damping, textColor }: MagneticLetterProps) {
  const ref = useRef<HTMLSpanElement>(null);
  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const springX = useSpring(x, { stiffness, damping });
  const springY = useSpring(y, { stiffness, damping });

  useEffect(() => {
    const handle = (e: MouseEvent) => {
      if (!ref.current) return;
      const rect = ref.current.getBoundingClientRect();
      const cx = rect.left + rect.width / 2;
      const cy = rect.top + rect.height / 2;
      const dx = e.clientX - cx;
      const dy = e.clientY - cy;
      const dist = Math.sqrt(dx * dx + dy * dy);
      const thresholdPx = rect.width * threshold;

      if (dist < thresholdPx) {
        const force = ((thresholdPx - dist) / thresholdPx) * strength;
        x.set((dx / thresholdPx) * force);
        y.set((dy / thresholdPx) * force);
      } else {
        x.set(0);
        y.set(0);
      }
    };

    window.addEventListener("mousemove", handle);
    return () => window.removeEventListener("mousemove", handle);
  }, [strength, threshold, x, y]);

  return (
    <motion.span
      ref={ref}
      style={{
        x: springX,
        y: springY,
        color: textColor,
      }}
      className="inline-block cursor-pointer select-none transition-colors duration-200"
    >
      {char === " " ? "\u00A0" : char}
    </motion.span>
  );
}

export function MagneticLetters({
  text,
  strength = 40,
  threshold = 6,
  stiffness = 400,
  damping = 30,
  textColor = "#007aff",
  className = "",
  style = {},
}: MagneticLettersProps) {
  return (
    <span className={`${className} inline-flex`} style={style}>
      {text.split("").map((char, i) => (
        <MagneticLetter
          key={i}
          char={char}
          strength={strength}
          threshold={threshold}
          stiffness={stiffness}
          damping={damping}
          textColor={textColor}
        />
      ))}
    </span>
  );
}

"use client";
import React from "react";
import { motion } from "framer-motion";

interface RevealTextProps {
  /** 등장 애니메이션을 적용할 문자열입니다. */
  text: string;
  /** 텍스트 바깥 span에 추가할 CSS 클래스입니다. */
  className?: string;
  /** 텍스트 바깥 span에 적용할 인라인 스타일입니다. */
  style?: React.CSSProperties;
  /**
   * 애니메이션 방향: up, down, left, right
   */
  direction?: "up" | "down" | "left" | "right";
  /**
   * 전체 애니메이션 시작 딜레이 (초)
   */
  delay?: number;
  /**
   * 각 글자/단어 애니메이션 지속시간 (초)
   */
  duration?: number;
  /**
   * 각 글자/단어 사이의 애니메이션 간격 (초)
   */
  stagger?: number;
  /**
   * 단어 단위로 애니메이션 적용 여부 (기본: false, 글자 단위)
   */
  byWord?: boolean;
}

/**
 * RevealText
 * - 텍스트가 한 글자씩 또는 한 단어씩 자연스럽게 나타나는 Reveal Animation
 * - direction, delay, duration, stagger 등 커스텀 prop 지원
 * - framer-motion의 motion.span 활용
 * - 반응형 및 접근성 고려
 */
const RevealText: React.FC<RevealTextProps> = ({
  text,
  className,
  style,
  direction = "up",
  delay = 0,
  duration = 0.5,
  stagger = 0.04,
  byWord = false,
}) => {
  // direction에 따라 초기 위치 설정
  const getInitial = () => {
    switch (direction) {
      case "up":
        return { y: "100%", opacity: 0 };
      case "down":
        return { y: "-100%", opacity: 0 };
      case "left":
        return { x: "-100%", opacity: 0 };
      case "right":
        return { x: "100%", opacity: 0 };
      default:
        return { y: "100%", opacity: 0 };
    }
  };

  // 텍스트를 글자 또는 단어 단위로 분리
  const units = byWord ? text.split(" ") : Array.from(text);

  return (
    <span className={`${className} inline-block overflow-hidden`} style={style} aria-label={text} role="text">
      {units.map((unit, i) => (
        <React.Fragment key={i}>
          <motion.span
            initial={getInitial()}
            animate={{ x: 0, y: 0, opacity: 1 }}
            transition={{
              delay: delay + i * stagger,
              duration,
              ease: "easeOut",
            }}
            className="inline-block"
          >
            {unit === " " ? "\u00A0" : unit}
          </motion.span>
          {byWord && i < units.length - 1 && <span className="inline-block">\u00A0</span>}
        </React.Fragment>
      ))}
    </span>
  );
};

export default RevealText;

"use client";
import React, { useCallback, useEffect, useState } from "react";
import { motion, useAnimation } from "framer-motion";

interface GlitchTextProps {
  /** 글리치 레이어에 반복해서 표시할 문자열입니다. */
  children: string;
  /** 글리치 전환 시간의 배율입니다. 값이 클수록 한 번의 전환이 느려집니다. */
  speed?: number;
  /** 네 가지 색상의 글리치 레이어를 표시할지 설정합니다. */
  enableShadows?: boolean;
  /** true이면 마우스를 올린 동안만 글리치를 반복합니다. */
  enableOnHover?: boolean;
  /** 텍스트와 글리치 레이어를 감싸는 span에 추가할 CSS 클래스입니다. */
  className?: string;
  /** 네 개 글리치 레이어에 순서대로 적용할 CSS 색상 배열입니다. 색상 네 개를 전달하세요. */
  glitchColors?: string[];
  /** 글리치 반복 사이의 기준 대기 시간(ms)입니다. 실제 간격은 무작위로 변합니다. */
  refreshDelay?: number;
}

// 강렬한 글리치 색상 (이미지 스타일)
const defaultGlitchColors = [
  "#ff0040", // 강렬한 빨강
  "#00ffff", // 시안
  "#ff0080", // 핑크
  "#0040ff", // 파랑
];

// 다양한 글리치 패턴 생성 함수들
function getRandomClip() {
  const patterns = [
    // 수평 슬라이스
    () => {
      const top = Math.random() * 80;
      const height = 5 + Math.random() * 20;
      return `inset(${top}% 0 ${100 - top - height}% 0)`;
    },
    // 대각선 슬라이스
    () => {
      const points = Array.from({ length: 4 }, () => Math.random() * 100);
      return `polygon(${points[0]}% ${points[1]}%, ${points[2]}% ${points[3]}%, ${100 - points[0]}% ${
        100 - points[1]
      }%, ${100 - points[2]}% ${100 - points[3]}%)`;
    },
    // 불규칙한 조각들
    () => {
      const x1 = Math.random() * 30;
      const x2 = 70 + Math.random() * 30;
      const y1 = Math.random() * 40;
      const y2 = 60 + Math.random() * 40;
      return `inset(${y1}% ${100 - x2}% ${100 - y2}% ${x1}%)`;
    },
  ];

  return patterns[Math.floor(Math.random() * patterns.length)]();
}

// 강렬한 변형 값들
function getRandomTransform() {
  return {
    x: (Math.random() - 0.5) * 20, // -10 ~ 10px
    y: (Math.random() - 0.5) * 8, // -4 ~ 4px
    skewX: (Math.random() - 0.5) * 10, // -5 ~ 5deg
    scale: 0.98 + Math.random() * 0.04, // 0.98 ~ 1.02
  };
}

const GlitchText: React.FC<GlitchTextProps> = ({
  children,
  speed = 0.5,
  enableShadows = true,
  enableOnHover = false,
  className = "",
  glitchColors = defaultGlitchColors,
  refreshDelay = 100,
}) => {
  const controls1 = useAnimation();
  const controls2 = useAnimation();
  const controls3 = useAnimation();
  const controls4 = useAnimation();
  const [isHovered, setIsHovered] = useState(false);
  const [shouldAnimate, setShouldAnimate] = useState(!enableOnHover);

  // 강렬한 글리치 애니메이션
  const performIntenseGlitch = useCallback(async () => {
    try {
      const duration = 0.1 * speed;

      // 4개 레이어로 더 복잡한 글리치
      const promises = [
        // 레이어 1: 빨간색 큰 오프셋
        controls1.start({
          clipPath: getRandomClip(),
          ...getRandomTransform(),
          x: [0, 15, -8, 0],
          color: enableShadows ? glitchColors[0] : "rgba(0,0,0,0)",
          opacity: [0.8, 1, 0.9, 0.8],
          transition: {
            duration: duration,
            ease: [0.25, 0.46, 0.45, 0.94],
            times: [0, 0.3, 0.7, 1],
          },
        }),

        // 레이어 2: 시안색 반대 방향
        controls2.start({
          clipPath: getRandomClip(),
          ...getRandomTransform(),
          x: [0, -12, 6, 0],
          y: [0, 2, -1, 0],
          color: enableShadows ? glitchColors[1] : "rgba(0,0,0,0)",
          opacity: [0.7, 0.9, 1, 0.7],
          transition: {
            duration: duration * 1.2,
            ease: [0.55, 0.055, 0.675, 0.19],
            times: [0, 0.4, 0.6, 1],
          },
        }),

        // 레이어 3: 핑크색 스큐 효과
        controls3.start({
          clipPath: getRandomClip(),
          ...getRandomTransform(),
          x: [0, 8, -15, 0],
          skewX: [0, 3, -2, 0],
          color: enableShadows ? glitchColors[2] : "rgba(0,0,0,0)",
          opacity: [0.6, 1, 0.8, 0.6],
          transition: {
            duration: duration * 0.8,
            ease: [0.175, 0.885, 0.32, 1.275],
            times: [0, 0.2, 0.8, 1],
          },
        }),

        // 레이어 4: 파란색 미세 진동
        controls4.start({
          clipPath: getRandomClip(),
          ...getRandomTransform(),
          x: [0, -5, 10, -3, 0],
          y: [0, 1, -2, 1, 0],
          color: enableShadows ? glitchColors[3] : "rgba(0,0,0,0)",
          opacity: [0.5, 0.8, 1, 0.7, 0.5],
          transition: {
            duration: duration * 1.5,
            ease: "linear",
            times: [0, 0.25, 0.5, 0.75, 1],
          },
        }),
      ];

      await Promise.all(promises);

      // 모든 레이어 리셋
      [controls1, controls2, controls3, controls4].forEach((control) => {
        control.set({
          clipPath: "none",
          x: 0,
          y: 0,
          skewX: 0,
          scale: 1,
          color: "rgba(0,0,0,0)",
          opacity: 0,
        });
      });
    } catch (error) {
      console.error("글리치 애니메이션 에러:", error);
    }
  }, [controls1, controls2, controls3, controls4, speed, enableShadows, glitchColors]);

  // 애니메이션 루프
  useEffect(() => {
    if (!shouldAnimate) return;

    let timeoutId: NodeJS.Timeout;
    let isActive = true;

    const animationLoop = async () => {
      if (!isActive) return;

      await performIntenseGlitch();

      if (isActive) {
        // 랜덤한 간격으로 더 자연스러운 글리치
        const randomDelay = refreshDelay + (Math.random() - 0.5) * refreshDelay * 0.5;
        timeoutId = setTimeout(animationLoop, randomDelay);
      }
    };

    // 초기 지연
    timeoutId = setTimeout(animationLoop, 300);

    return () => {
      isActive = false;
      if (timeoutId) clearTimeout(timeoutId);
    };
  }, [shouldAnimate, performIntenseGlitch, refreshDelay]);

  // 호버 상태 관리
  useEffect(() => {
    if (enableOnHover) {
      setShouldAnimate(isHovered);
    } else {
      setShouldAnimate(true);
    }
  }, [enableOnHover, isHovered]);

  // 호버 이벤트 핸들러
  const handleMouseEnter = () => {
    if (enableOnHover) {
      setIsHovered(true);
    }
  };

  const handleMouseLeave = () => {
    if (enableOnHover) {
      setIsHovered(false);
      // 호버 종료시 모든 레이어 리셋
      [controls1, controls2, controls3, controls4].forEach((control) => {
        control.set({
          clipPath: "none",
          x: 0,
          y: 0,
          skewX: 0,
          scale: 1,
          color: "rgba(0,0,0,0)",
          opacity: 0,
        });
      });
    }
  };

  return (
    <span
      className={`${className} relative inline-block font-bold cursor-pointer`}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      aria-label={children}
      style={{
        textShadow: shouldAnimate ? "0 0 10px rgba(255,255,255,0.1)" : "none",
      }}
    >
      {/* 메인 텍스트 */}
      <span className="relative z-10">{children}</span>

      {/* 글리치 레이어 1 - 빨간색 */}
      <motion.span
        aria-hidden
        className="pointer-events-none absolute inset-0 z-[1] select-none font-bold"
        animate={controls1}
        initial={{ clipPath: "none", x: 0, y: 0, skewX: 0, scale: 1, color: "rgba(0,0,0,0)", opacity: 0 }}
        style={{
          display: "block",
          overflow: "hidden",
          whiteSpace: "pre",
          mixBlendMode: "screen",
        }}
      >
        {children}
      </motion.span>

      {/* 글리치 레이어 2 - 시안색 */}
      <motion.span
        aria-hidden
        className="pointer-events-none absolute inset-0 z-[2] select-none font-bold"
        animate={controls2}
        initial={{ clipPath: "none", x: 0, y: 0, skewX: 0, scale: 1, color: "rgba(0,0,0,0)", opacity: 0 }}
        style={{
          display: "block",
          overflow: "hidden",
          whiteSpace: "pre",
          mixBlendMode: "screen",
        }}
      >
        {children}
      </motion.span>

      {/* 글리치 레이어 3 - 핑크색 */}
      <motion.span
        aria-hidden
        className="pointer-events-none absolute inset-0 z-[3] select-none font-bold"
        animate={controls3}
        initial={{ clipPath: "none", x: 0, y: 0, skewX: 0, scale: 1, color: "rgba(0,0,0,0)", opacity: 0 }}
        style={{
          display: "block",
          overflow: "hidden",
          whiteSpace: "pre",
          mixBlendMode: "screen",
        }}
      >
        {children}
      </motion.span>

      {/* 글리치 레이어 4 - 파란색 */}
      <motion.span
        aria-hidden
        className="pointer-events-none absolute inset-0 z-[4] select-none font-bold"
        animate={controls4}
        initial={{ clipPath: "none", x: 0, y: 0, skewX: 0, scale: 1, color: "rgba(0,0,0,0)", opacity: 0 }}
        style={{
          display: "block",
          overflow: "hidden",
          whiteSpace: "pre",
          mixBlendMode: "screen",
        }}
      >
        {children}
      </motion.span>
    </span>
  );
};

