"use client";
import { useEffect, useRef, useState } from "react";
import { motion, useAnimationControls } from "framer-motion";
import { twMerge } from "tailwind-merge";

interface ScrollMarqueeTextProps {
  /** 이어 붙여 반복해서 흘려보낼 문자열 배열입니다. */
  texts: string[];
  /** 기본 이동량 계수입니다. 프레임마다 값의 0.1배(px)만큼 이동하며 스크롤 중에는 가속됩니다. */
  baseSpeed?: number;
  /** 텍스트의 CSS 글꼴 크기입니다. px, rem, vw 등의 단위를 포함하세요. */
  fontSize?: string;
  /** 흘러가는 텍스트의 CSS 색상입니다. */
  color?: string;
  /** 마퀴 컨테이너의 CSS 배경색입니다. */
  backgroundColor?: string;
  /** 마퀴 바깥 컨테이너에 추가할 CSS 클래스입니다. */
  className?: string;
  /** 움직이는 텍스트 요소의 인라인 스타일입니다. fontSize와 color 설정을 덮어쓸 수 있습니다. */
  style?: React.CSSProperties;
  /**
   * direction: false(기본값) = 왼쪽, true = 오른쪽
   */
  direction?: boolean;
}

export default function ScrollMarqueeText({
  texts,
  baseSpeed = 50,
  fontSize = "5vw",
  color = "#000",
  backgroundColor = "transparent",
  className,
  style,
  direction = false, // 기본값: 왼쪽
}: ScrollMarqueeTextProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [duplicatedTexts, setDuplicatedTexts] = useState<string[]>([]);
  const controls = useAnimationControls();
  const [scrollSpeed, setScrollSpeed] = useState(baseSpeed);
  const countRef = useRef(0);

  // 텍스트 배열 2배로 복제
  useEffect(() => {
    setDuplicatedTexts([...texts, ...texts]);
  }, [texts]);

  // 스크롤 이벤트에 따른 속도 조절
  useEffect(() => {
    let lastScrollY = window.scrollY;
    let scrollTimeout: NodeJS.Timeout;

    const handleScroll = () => {
      const currentScrollY = window.scrollY;
      const scrollDiff = Math.abs(currentScrollY - lastScrollY);

      // 스크롤 속도에 따라 마키 속도 증가
      setScrollSpeed(baseSpeed + scrollDiff * 2);

      // 일정 시간 후 원래 속도로 복귀
      clearTimeout(scrollTimeout);
      scrollTimeout = setTimeout(() => {
        setScrollSpeed(baseSpeed);
      }, 150);

      lastScrollY = currentScrollY;
    };

    window.addEventListener("scroll", handleScroll);
    return () => {
      window.removeEventListener("scroll", handleScroll);
      clearTimeout(scrollTimeout);
    };
  }, [baseSpeed]);

  // 무한 스크롤 애니메이션 (방향에 따라 x값 증감)
  useEffect(() => {
    let animationFrame: number;

    const animate = () => {
      if (!containerRef.current) return;

      const halfWidth = containerRef.current.scrollWidth / 2;

      // 오른쪽 방향일 때는 -halfWidth에서 0까지 이동, 왼쪽은 0에서 -halfWidth까지 이동
      if (direction) {
        // 초기값 세팅 (최초 0이면 -halfWidth로)
        if (countRef.current === 0) {
          countRef.current = -halfWidth;
        }
        countRef.current += scrollSpeed * 0.1;
        if (countRef.current >= 0) {
          countRef.current = -halfWidth;
        }
      } else {
        countRef.current -= scrollSpeed * 0.1;
        if (countRef.current <= -halfWidth) {
          countRef.current = 0;
        }
      }

      controls.set({ x: countRef.current });
      animationFrame = requestAnimationFrame(animate);
    };

    animationFrame = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(animationFrame);
  }, [scrollSpeed, controls, direction]);

  return (
    <div
      ref={containerRef}
      className={twMerge("w-full overflow-hidden whitespace-nowrap relative", className)}
      style={{ backgroundColor }}
    >
      <motion.div
        animate={controls}
        className="inline-block whitespace-nowrap py-4"
        style={{
          fontSize,
          color,
          ...style,
        }}
      >
        {duplicatedTexts.map((text, index) => (
          <span key={index} className="mr-8">
            {text}
          </span>
        ))}
      </motion.div>
    </div>
  );
}

"use client";
import { motion, useScroll, useMotionValueEvent } from "framer-motion";
import { useRef, useState } from "react";

interface ScrollTriggerTextProps {
  /** 글자의 활성 스크롤 구간 밖에서 사용하는 CSS 색상입니다. */
  fromColor?: string;
  /** 각 글자의 활성 스크롤 구간에서 사용하는 CSS 색상입니다. */
  toColor?: string;
  /** 글자 색상이 바뀌는 CSS 전환 시간(초)입니다. */
  duration?: number;
  /** 스크롤 진행도에 따라 글자별로 표시할 문자열입니다. */
  text?: string;
  /** 텍스트의 CSS 글꼴 크기입니다. 단위를 포함한 문자열을 전달하세요. */
  fontSize?: string;
  /** 타입에 선언되어 있지만 현재 구현에서 사용하지 않습니다. */
  initialX?: number;
  /** 타입에 선언되어 있지만 현재 구현에서 사용하지 않습니다. */
  finalX?: number;
  /** 각 글자의 등장 시작 배율입니다. 진행도에 따라 1까지 커집니다. */
  initialScale?: number;
  /** 타입에 선언되어 있지만 현재 구현에서 사용하지 않습니다. */
  finalScale?: number;
  /** 텍스트를 표시하는 h1 요소에 추가할 CSS 클래스입니다. */
  className?: string;
}

export default function ScrollTriggerText({
  fromColor = "#888",
  toColor = "#FFD600",
  duration = 0.8,
  text = "Scroll Trigger Text Scroll Trigger Text Scroll Trigger Text Scroll Trigger Text Scroll Trigger Text Scroll Trigger Text",
  fontSize = "5vw",
  className,
  initialScale = 0.8,
}: ScrollTriggerTextProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start end", "end start"],
  });

  const chars = Array.from(text);
  const [progress, setProgress] = useState(0);
  useMotionValueEvent(scrollYProgress, "change", (v) => setProgress(v));

  // 글자별 스타일 계산 함수
  function getCharStyle(i: number) {
    const spread = 0.5;
    const base = 0.2;
    const step = spread / Math.max(chars.length - 1, 1);
    const start = base + i * step;
    const end = start + 0.18;

    // opacity 계산
    let opacity = 0;
    if (progress >= start && progress <= end) {
      opacity = (progress - start) / (end - start);
    } else if (progress > end && progress < 1) {
      opacity = 1;
    }
    // scale 계산
    let scale = initialScale;
    if (progress >= start && progress <= end) {
      scale = initialScale + ((1 - initialScale) * (progress - start)) / (end - start);
    } else if (progress > end && progress < 1) {
      scale = 1;
    }
    // color 계산 (간단히 fromColor/toColor 중간값, 실제로는 보간 필요)
    const color = progress >= start && progress <= end ? toColor : fromColor;

    return {
      opacity,
      scale,
      color,
      transition: `color ${duration}s ease`,
      whiteSpace: chars[i] === " " ? "pre" : undefined,
      display: "inline-block",
    };
  }

  return (
    <div ref={containerRef}>
      <motion.h1
        style={{
          fontSize,
          transition: `color ${duration}s ease`,
        }}
        className={className}
      >
        {chars.map((char, i) => (
          <span key={i} style={getCharStyle(i)}>
            {char === " " ? "\u00A0" : char}
          </span>
        ))}
      </motion.h1>
    </div>
  );
}

"use client";
import { useRef, useEffect } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import styles from "./TextClipEffect.module.css";

gsap.registerPlugin(ScrollTrigger);

export type TextClipEffectItemProps = {
  /** 클립 효과 아래에 표시할 기본 문자열입니다. */
  main: string;
  /** 마우스를 올렸을 때 클립 영역에 표시할 React 콘텐츠입니다. */
  sub: React.ReactNode;
  /** 텍스트 h1 요소에 추가할 CSS 클래스입니다. */
  className?: string;
  /** 마우스 호버 시 드러나는 보조 콘텐츠 영역의 CSS 배경색입니다. */
  clipColor?: string;
  /** GSAP ScrollTrigger의 시작·종료 위치 표시를 켭니다. */
  showMarkers?: boolean;
  /** 애니메이션 시작 위치를 정하는 GSAP ScrollTrigger 표현식입니다. */
  startPosition?: string;
  /** 애니메이션 종료 위치를 정하는 GSAP ScrollTrigger 표현식입니다. */
  endPosition?: string;
  /** true이면 배경 채우기 진행도를 스크롤 위치에 직접 연결합니다. */
  scrubEffect?: boolean;
};

export default function TextClipEffectItem({
  main,
  sub,
  className,
  clipColor = "#fff",
  showMarkers = false,
  startPosition = "center 80%",
  endPosition = "center 20%",
  scrubEffect = true,
}: TextClipEffectItemProps) {
  const textRef = useRef<HTMLHeadingElement>(null);

  useEffect(() => {
    const textElement = textRef.current;

    if (textElement) {
      // 기존 ScrollTrigger 제거
      ScrollTrigger.getAll().forEach((trigger) => {
        if (trigger.trigger === textElement) {
          trigger.kill();
        }
      });

      gsap.to(textElement, {
        backgroundSize: "100%",
        ease: "none",
        scrollTrigger: {
          trigger: textElement,
          start: startPosition,
          end: endPosition,
          scrub: scrubEffect,
          markers: showMarkers,
        },
      });
    }

    return () => {
      // 컴포넌트 언마운트 시 ScrollTrigger 정리
      ScrollTrigger.getAll().forEach((trigger) => {
        if (trigger.trigger === textElement) {
          trigger.kill();
        }
      });
    };
  }, [showMarkers, startPosition, endPosition, scrubEffect]);

  return (
    <h1 ref={textRef} className={`${styles.text} ${className}`}>
      {main}
      <span className={styles.span} style={{ backgroundColor: clipColor }}>
        {sub}
      </span>
    </h1>
  );
}

.container {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  height: 100vh;
}

.text {
  font-size: 10vw;
  letter-spacing: -0.01em;
  line-height: 100%;
  margin: 0;
