import React, { useEffect, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { useCursor } from "./CursorContext";

export default function GlobalCursor() {
  const { cursorText, cursorColor, cursorSize } = useCursor();
  const [pos, setPos] = useState({ x: 0, y: 0 });
  const [visible, setVisible] = useState(true);

  useEffect(() => {
    const handleMove = (e: MouseEvent) => {
      setPos({ x: e.clientX, y: e.clientY });
    };
    const handleEnter = () => setVisible(true);
    const handleLeave = () => setVisible(false);
    window.addEventListener("mousemove", handleMove);
    window.addEventListener("mouseenter", handleEnter);
    window.addEventListener("mouseleave", handleLeave);
    return () => {
      window.removeEventListener("mousemove", handleMove);
      window.removeEventListener("mouseenter", handleEnter);
      window.removeEventListener("mouseleave", handleLeave);
    };
  }, []);

  return (
    <AnimatePresence>
      {visible && (
        <motion.div
          key="global-cursor"
          initial={{ opacity: 0, scale: 0.7, x: pos.x - (cursorSize || 48) / 2, y: pos.y - (cursorSize || 48) / 2 }}
          animate={{
            opacity: 1,
            scale: 1,
            x: pos.x - (cursorSize || 48) / 2,
            y: pos.y - (cursorSize || 48) / 2,
            transition: { type: "spring", stiffness: 300, damping: 30 },
          }}
          exit={{ opacity: 0, scale: 0.7 }}
          className="pointer-events-none fixed left-0 top-0 z-[9999] flex select-none items-center justify-center rounded-full font-bold text-white mix-blend-multiply shadow-[0_4px_24px_rgba(255,105,180,0.18)]"
          style={{
            width: cursorSize || 48,
            height: cursorSize || 48,
            background: cursorColor || "#ff69b4",
            fontSize: (cursorSize || 48) * 0.22,
          }}
          aria-hidden
        >
          {cursorText}
        </motion.div>
      )}
    </AnimatePresence>
  );
}

"use client";
import { useEffect, useRef, useState } from "react";
import { motion, useAnimation, useMotionValue, useSpring } from "framer-motion";

/**
 * SVG로 네 귀퉁이만 있는 사각 테두리와 중앙 원을 그리는 커스텀 커서 컴포넌트입니다.
 * framer-motion을 활용해 커서가 자연스럽게 회전하는 애니메이션이 적용됩니다.
 * 마우스 위치 추적 및 마그네틱 효과는 추후 구현 예정입니다.
 */
const CURSOR_SIZE = 40;

function isMobile() {
  if (typeof navigator === "undefined") return false;
  return /Mobi|Android|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
}

export default function MagneticCursor() {
  const controls = useAnimation();
  const cursorRef = useRef<HTMLDivElement>(null);

  // 초기값 0으로 설정 (SSR 안전)
  const mouseX = useMotionValue(0);
  const mouseY = useMotionValue(0);
  // spring 효과로 부드럽게 이동
  const springX = useSpring(mouseX, { stiffness: 350, damping: 30 });
  const springY = useSpring(mouseY, { stiffness: 350, damping: 30 });

  // 커서 크기/회전 상태
  const [cursorBox, setCursorBox] = useState<{ width: number; height: number } | null>(null);
  const [cursorRotate, setCursorRotate] = useState(0);
  const [isMagnetic, setIsMagnetic] = useState(false);

  // 마운트 시 브라우저에서만 중앙으로 세팅
  useEffect(() => {
    if (typeof window !== "undefined") {
      mouseX.set(window.innerWidth / 2);
      mouseY.set(window.innerHeight / 2);
    }
  }, [mouseX, mouseY]);

  // 무한 회전 애니메이션 (기본 상태)
  useEffect(() => {
    if (!isMagnetic) {
      controls.start({
        rotate: 360,
        transition: {
          repeat: Infinity,
          ease: "linear",
          duration: 1.2,
        },
      });
    } else {
      controls.stop();
      controls.set({ rotate: cursorRotate });
    }
  }, [controls, isMagnetic, cursorRotate]);

  // 마우스 위치 추적 (기본 상태)
  useEffect(() => {
    if (isMobile()) return;
    if (isMagnetic) return; // 마그네틱 상태에서는 별도 처리
    const handleMove = (e: MouseEvent) => {
      mouseX.set(e.clientX);
      mouseY.set(e.clientY);
    };
    window.addEventListener("mousemove", handleMove);
    return () => window.removeEventListener("mousemove", handleMove);
  }, [mouseX, mouseY, isMagnetic]);

  // 기본 커서 숨김
  useEffect(() => {
    if (isMobile()) return;
    const prev = document.body.style.cursor;
    document.body.style.cursor = "none";
    return () => {
      document.body.style.cursor = prev;
    };
  }, []);

  // 마그네틱 타겟 진입/이탈 이벤트 리스닝
  useEffect(() => {
    if (isMobile()) return;
    let lastRect: DOMRect | null = null;
    let lastBoxCenter = { x: 0, y: 0 };
    let lastBoxWidth = CURSOR_SIZE;
    let lastBoxHeight = CURSOR_SIZE;
    let lastRotate = 0;

    // 박스 내부 마우스 이동 핸들러
    const handleBoxMove = (e: MouseEvent) => {
      if (!lastRect) return;
      // 박스 내 마우스 좌표 (0~1)
      const relX = (e.clientX - lastRect.left) / lastRect.width;
      const relY = (e.clientY - lastRect.top) / lastRect.height;
      // 커서가 박스 중앙에서 살짝 벗어나도록(자석 효과)
      const offsetX = (relX - 0.5) * lastRect.width * 0.3;
      const offsetY = (relY - 0.5) * lastRect.height * 0.3;
      mouseX.set(lastBoxCenter.x + offsetX);
      mouseY.set(lastBoxCenter.y + offsetY);
    };

    // 타겟 진입 시
    const handleEnter = (e: CustomEvent) => {
      const rect: DOMRect = e.detail.rect;
      lastRect = rect;
      lastBoxCenter = {
        x: rect.left + rect.width / 2,
        y: rect.top + rect.height / 2,
      };
      lastBoxWidth = rect.width + 16; // 박스보다 16px 크게
      lastBoxHeight = rect.height + 16;
      lastRotate = 0;
      setIsMagnetic(true);
      setCursorBox({ width: lastBoxWidth, height: lastBoxHeight });
      setCursorRotate(lastRotate);
      // 커서를 박스 중앙으로 이동
      mouseX.set(lastBoxCenter.x);
      mouseY.set(lastBoxCenter.y);
      // 박스 내부 마우스 이동 추적
      window.addEventListener("mousemove", handleBoxMove);
    };
    // 타겟 이탈 시
    const handleLeave = () => {
      setIsMagnetic(false);
      setCursorBox(null);
      setCursorRotate(0);
      lastRect = null;
      // 커서가 원래 마우스 위치로 복귀하도록(마우스 위치 추적 재개)
      window.removeEventListener("mousemove", handleBoxMove);
    };
    window.addEventListener("magnetic-cursor:enter", handleEnter as EventListener);
    window.addEventListener("magnetic-cursor:leave", handleLeave);
    return () => {
      window.removeEventListener("magnetic-cursor:enter", handleEnter as EventListener);
      window.removeEventListener("magnetic-cursor:leave", handleLeave);
      window.removeEventListener("mousemove", handleBoxMove);
    };
  }, [mouseX, mouseY]);

  // 모바일에서는 렌더링하지 않음
  if (isMobile()) return null;

  return (
    <motion.div
      ref={cursorRef}
      animate={controls}
      className="pointer-events-none fixed left-0 top-0 z-[9999] mix-blend-difference transition-[width,height] duration-150"
      style={{
        x: springX,
        y: springY,
        width: isMagnetic && cursorBox ? cursorBox.width : CURSOR_SIZE,
        height: isMagnetic && cursorBox ? cursorBox.height : CURSOR_SIZE,
        translateX: "-50%",
        translateY: "-50%",
      }}
    >
      <svg
        width={isMagnetic && cursorBox ? cursorBox.width : CURSOR_SIZE}
        height={isMagnetic && cursorBox ? cursorBox.height : CURSOR_SIZE}
        viewBox={`0 0 ${isMagnetic && cursorBox ? cursorBox.width : CURSOR_SIZE} ${
          isMagnetic && cursorBox ? cursorBox.height : CURSOR_SIZE
        }`}
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        className="block transition-all duration-150"
      >
        {/* 네 귀퉁이만 있는 사각 테두리 */}
        <g stroke="#fff" strokeWidth={3}>
          {/* 왼쪽 위 */}
          <line x1={8} y1={8} x2={(isMagnetic && cursorBox ? cursorBox.width : CURSOR_SIZE) * 0.28} y2={8} />
          <line x1={8} y1={8} x2={8} y2={(isMagnetic && cursorBox ? cursorBox.height : CURSOR_SIZE) * 0.28} />
          {/* 오른쪽 위 */}
          <line
            x1={(isMagnetic && cursorBox ? cursorBox.width : CURSOR_SIZE) - 8}
            y1={8}
            x2={(isMagnetic && cursorBox ? cursorBox.width : CURSOR_SIZE) * 0.72}
            y2={8}
          />
          <line
            x1={(isMagnetic && cursorBox ? cursorBox.width : CURSOR_SIZE) - 8}
            y1={8}
            x2={(isMagnetic && cursorBox ? cursorBox.width : CURSOR_SIZE) - 8}
            y2={(isMagnetic && cursorBox ? cursorBox.height : CURSOR_SIZE) * 0.28}
          />
          {/* 왼쪽 아래 */}
          <line
            x1={8}
            y1={(isMagnetic && cursorBox ? cursorBox.height : CURSOR_SIZE) - 8}
            x2={8}
            y2={(isMagnetic && cursorBox ? cursorBox.height : CURSOR_SIZE) * 0.72}
          />
          <line
            x1={8}
            y1={(isMagnetic && cursorBox ? cursorBox.height : CURSOR_SIZE) - 8}
            x2={(isMagnetic && cursorBox ? cursorBox.width : CURSOR_SIZE) * 0.28}
            y2={(isMagnetic && cursorBox ? cursorBox.height : CURSOR_SIZE) - 8}
          />
          {/* 오른쪽 아래 */}
          <line
            x1={(isMagnetic && cursorBox ? cursorBox.width : CURSOR_SIZE) - 8}
            y1={(isMagnetic && cursorBox ? cursorBox.height : CURSOR_SIZE) - 8}
            x2={(isMagnetic && cursorBox ? cursorBox.width : CURSOR_SIZE) * 0.72}
            y2={(isMagnetic && cursorBox ? cursorBox.height : CURSOR_SIZE) - 8}
          />
          <line
            x1={(isMagnetic && cursorBox ? cursorBox.width : CURSOR_SIZE) - 8}
            y1={(isMagnetic && cursorBox ? cursorBox.height : CURSOR_SIZE) - 8}
            x2={(isMagnetic && cursorBox ? cursorBox.width : CURSOR_SIZE) - 8}
            y2={(isMagnetic && cursorBox ? cursorBox.height : CURSOR_SIZE) * 0.72}
          />
        </g>
        {/* 중앙 원 */}
        <circle
          cx={(isMagnetic && cursorBox ? cursorBox.width : CURSOR_SIZE) / 2}
          cy={(isMagnetic && cursorBox ? cursorBox.height : CURSOR_SIZE) / 2}
          r={CURSOR_SIZE / 8}
          fill="#fff"
        />
      </svg>
    </motion.div>
  );
}

"use client";
import React, { useRef, useEffect } from "react";

/**
 * MagneticTargetBox: 마그네틱 커서와 상호작용하는 타겟 박스 컴포넌트
 * - 자신의 위치/크기를 ref로 측정
 * - 마우스가 박스 위에 들어오면 커스텀 커서에 신호를 전달할 수 있도록 커스텀 이벤트 디스패치
 * - 기본 스타일(점선 테두리, 중앙 정렬 텍스트, 반응형) 적용
 */
interface MagneticTargetBoxProps {
  children: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
}

export default function MagneticTargetBox({ children, className, style }: MagneticTargetBoxProps) {
  const boxRef = useRef<HTMLDivElement>(null);

  // 마우스가 박스 위에 들어오고 나갈 때 커스텀 이벤트 디스패치
  useEffect(() => {
    const box = boxRef.current;
    if (!box) return;
    const handleEnter = () => {
      const rect = box.getBoundingClientRect();
      window.dispatchEvent(
        new CustomEvent("magnetic-cursor:enter", {
          detail: {
            rect,
          },
        })
      );
    };
    const handleLeave = () => {
      window.dispatchEvent(new CustomEvent("magnetic-cursor:leave"));
    };
    box.addEventListener("mouseenter", handleEnter);
    box.addEventListener("mouseleave", handleLeave);
    return () => {
      box.removeEventListener("mouseenter", handleEnter);
      box.removeEventListener("mouseleave", handleLeave);
    };
  }, []);

  return (
    <div
      ref={boxRef}
      style={style}
      className={`${className} relative flex min-h-[48px] min-w-[120px] cursor-pointer select-none items-center justify-center border border-dashed border-white bg-transparent text-2xl font-semibold text-white transition-shadow duration-200`}
    >
      {children}
    </div>
  );
}

"use client";

import React, { useRef, useEffect, useCallback } from "react";

interface NoiseGrainBGProps {
  /** 콘텐츠 위에 겹치는 노이즈 레이어의 불투명도(0~1)입니다. */
  opacity?: number;
  /** SVG 노이즈의 기본 주파수입니다. 값이 높을수록 입자가 촘촘해집니다. */
  baseFrequency?: number;
  /** SVG 노이즈를 합성할 옥타브 수입니다. 값이 높을수록 세부 무늬가 늘어납니다. */
  numOctaves?: number;
  /** 노이즈 시드를 주기적으로 바꿀지 설정합니다. */
  animate?: boolean;
  /** 애니메이션 중 초당 노이즈 시드를 갱신할 횟수입니다. 0보다 큰 값을 사용하세요. */
  speed?: number;
  /** 노이즈와 콘텐츠를 합성할 CSS mix-blend-mode 값입니다. */
  blendMode?: string;
  /** 노이즈와 콘텐츠를 감싸는 컨테이너에 추가할 CSS 클래스입니다. */
  className?: string;
  /** 노이즈 아래에 표시할 React 콘텐츠입니다. */
  children?: React.ReactNode;
}

const NoiseGrainBG: React.FC<NoiseGrainBGProps> = ({
  opacity = 0.15,
  baseFrequency = 0.65,
  numOctaves = 4,
  animate = true,
  speed = 10,
  blendMode = "overlay",
  className = "",
  children,
}) => {
  const turbulenceRef = useRef<SVGFETurbulenceElement>(null);
  const rafRef = useRef<number>(0);
  const seedRef = useRef<number>(0);
  const lastFrameTimeRef = useRef<number>(0);

  const animateGrain = useCallback(
    (time: number) => {
      if (!turbulenceRef.current) return;

      const interval = 1000 / speed;
      if (time - lastFrameTimeRef.current >= interval) {
        seedRef.current = (seedRef.current + 1) % 100;
        turbulenceRef.current.setAttribute("seed", String(seedRef.current));
        lastFrameTimeRef.current = time;
      }

      rafRef.current = requestAnimationFrame(animateGrain);
    },
    [speed],
  );

  useEffect(() => {
    if (animate) {
      rafRef.current = requestAnimationFrame(animateGrain);
    }

    return () => {
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current);
      }
    };
  }, [animate, animateGrain]);

  const filterId = `noise-grain-${React.useId().replace(/:/g, "")}`;

  return (
    <div className={`relative ${className}`}>
      {children}
      <div
        className="absolute inset-0 pointer-events-none"
        style={{
          mixBlendMode: blendMode as React.CSSProperties["mixBlendMode"],
          opacity,
        }}
      >
        <svg className="w-full h-full" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
          <filter id={filterId}>
            <feTurbulence
              ref={turbulenceRef}
              type="fractalNoise"
              baseFrequency={baseFrequency}
              numOctaves={numOctaves}
              stitchTiles="stitch"
              seed="0"
            />
          </filter>
          <rect width="100%" height="100%" filter={`url(#${filterId})`} />
        </svg>
      </div>
    </div>
  );
};

export default NoiseGrainBG;

"use client";

import React, { useRef, useEffect, useCallback } from "react";

interface DotGridBGProps {
  /** 기본 점의 반지름(px)입니다. 마우스 주변에서는 확대 배율이 곱해집니다. */
  dotSize?: number;
  /** 점의 6자리 HEX 색상입니다. 예: #ffffff. */
  dotColor?: string;
  /** 점 사이의 가로·세로 간격(px)입니다. 0보다 큰 값을 사용하세요. */
  dotSpacing?: number;
  /** 마우스 위치를 중심으로 점이 반응하는 반경(px)입니다. */
  interactionRadius?: number;
  /** 마우스에 가장 가까운 점에 적용할 최대 크기 배율입니다. */
  maxDotScale?: number;
  /** 마우스 주변의 가까운 점들을 선으로 연결할지 설정합니다. */
  showLines?: boolean;
  /** 연결선의 6자리 HEX 색상입니다. 예: #ffffff. */
  lineColor?: string;
  /** 연결선 불투명도의 상한(0~1)입니다. 점 사이 거리가 멀수록 투명해집니다. */
  lineOpacity?: number;
  /** 캔버스와 콘텐츠를 감싸는 컨테이너의 CSS 클래스입니다. 높이를 확보하세요. */
  className?: string;
  /** 점 그리드 위에 표시할 콘텐츠입니다. 이 콘텐츠 영역은 마우스 이벤트를 통과시킵니다. */
  children?: React.ReactNode;
}

export default function DotGridBG({
  dotSize = 1,
  dotColor = "#ffffff",
  dotSpacing = 30,
  interactionRadius = 120,
  maxDotScale = 3,
  showLines = true,
  lineColor = "#ffffff",
  lineOpacity = 0.15,
  className = "",
  children,
}: DotGridBGProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const mouseRef = useRef<{ x: number; y: number; active: boolean }>({
    x: -9999,
    y: -9999,
    active: false,
  });
  const rafRef = useRef<number>(0);

  const hexToRgb = useCallback((hex: string) => {
    const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
    return result
      ? {
          r: parseInt(result[1], 16),
          g: parseInt(result[2], 16),
          b: parseInt(result[3], 16),
        }
      : { r: 255, g: 255, b: 255 };
  }, []);

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const width = canvas.width;
    const height = canvas.height;
    const mouse = mouseRef.current;
    const dotRgb = hexToRgb(dotColor);
    const lineRgb = hexToRgb(lineColor);
    const radiusSq = interactionRadius * interactionRadius;

    ctx.clearRect(0, 0, width, height);

    // Collect active dots for line drawing
    const activeDots: { x: number; y: number; scale: number }[] = [];

    for (let x = dotSpacing; x < width; x += dotSpacing) {
      for (let y = dotSpacing; y < height; y += dotSpacing) {
        const dx = x - mouse.x;
        const dy = y - mouse.y;
        const distSq = dx * dx + dy * dy;

        let scale = 1;
        let alpha = 0.3;

        if (mouse.active && distSq < radiusSq) {
          const dist = Math.sqrt(distSq);
          const t = 1 - dist / interactionRadius;
          scale = 1 + (maxDotScale - 1) * t;
          alpha = 0.3 + 0.7 * t;
          activeDots.push({ x, y, scale });
        }

        ctx.beginPath();
        ctx.arc(x, y, dotSize * scale, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${dotRgb.r}, ${dotRgb.g}, ${dotRgb.b}, ${alpha})`;
        ctx.fill();
      }
    }

    // Draw lines between nearby active dots
    if (showLines && activeDots.length > 1) {
      const maxLineDist = dotSpacing * 2;
      const maxLineDistSq = maxLineDist * maxLineDist;

      for (let i = 0; i < activeDots.length; i++) {
        for (let j = i + 1; j < activeDots.length; j++) {
          const a = activeDots[i];
          const b = activeDots[j];
          const ldx = a.x - b.x;
          const ldy = a.y - b.y;
          const ldistSq = ldx * ldx + ldy * ldy;

          if (ldistSq < maxLineDistSq) {
            const ldist = Math.sqrt(ldistSq);
            const lineAlpha = lineOpacity * (1 - ldist / maxLineDist);
            ctx.beginPath();
            ctx.moveTo(a.x, a.y);
            ctx.lineTo(b.x, b.y);
            ctx.strokeStyle = `rgba(${lineRgb.r}, ${lineRgb.g}, ${lineRgb.b}, ${lineAlpha})`;
            ctx.lineWidth = 0.5;
            ctx.stroke();
          }
        }
      }
    }
  }, [
    dotSize,
    dotColor,
    dotSpacing,
    interactionRadius,
    maxDotScale,
    showLines,
    lineColor,
    lineOpacity,
    hexToRgb,
  ]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const resizeCanvas = () => {
      const parent = canvas.parentElement;
      if (!parent) return;
      const dpr = window.devicePixelRatio || 1;
      const rect = parent.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      canvas.style.width = `${rect.width}px`;
      canvas.style.height = `${rect.height}px`;
      const ctx = canvas.getContext("2d");
      if (ctx) ctx.scale(dpr, dpr);
      draw();
    };

    const handleMouseMove = (e: MouseEvent) => {
      const rect = canvas.getBoundingClientRect();
      mouseRef.current = {
        x: e.clientX - rect.left,
        y: e.clientY - rect.top,
        active: true,
      };
      cancelAnimationFrame(rafRef.current);
      rafRef.current = requestAnimationFrame(draw);
    };

    const handleMouseLeave = () => {
      mouseRef.current = { x: -9999, y: -9999, active: false };
      cancelAnimationFrame(rafRef.current);
      rafRef.current = requestAnimationFrame(draw);
    };

    resizeCanvas();

    const observer = new ResizeObserver(() => {
      resizeCanvas();
    });
    if (canvas.parentElement) {
      observer.observe(canvas.parentElement);
    }

    canvas.addEventListener("mousemove", handleMouseMove);
    canvas.addEventListener("mouseleave", handleMouseLeave);

    return () => {
      observer.disconnect();
      canvas.removeEventListener("mousemove", handleMouseMove);
      canvas.removeEventListener("mouseleave", handleMouseLeave);
      cancelAnimationFrame(rafRef.current);
    };
  }, [draw]);

  return (
    <div className={`relative ${className}`}>
      <canvas ref={canvasRef} className="absolute inset-0 pointer-events-auto" style={{ display: "block" }} />
      {children && <div className="relative z-10 pointer-events-none">{children}</div>}
    </div>
  );
}

"use client";

import { useRef, useCallback, ReactNode } from "react";

interface GlassmorphismCardProps {
  /** 배경 블러 강도 (px) */
  blurAmount?: number;
  /** 배경색 불투명도 */
  bgOpacity?: number;
  /** 배경 틴트 색상 */
  bgColor?: string;
  /** 빛 반사 효과 사용 여부 */
  enableReflection?: boolean;
  /** 빛 반사 크기 (px) */
  reflectionSize?: number;
  /** 빛 반사 불투명도 */
  reflectionOpacity?: number;
  /** 3D 틸트 효과 사용 */
  enableTilt?: boolean;
  /** 최대 틸트 각도 (deg) */
  maxTilt?: number;
  /** 엣지 하이라이트 불투명도 */
  edgeHighlight?: number;
  /** 표면 노이즈 불투명도 */
  noiseOpacity?: number;
  /** 내부 그림자 강도 */
  innerShadow?: number;
  /** 너비 (Tailwind 클래스) */
  width?: string;
  /** 높이 (Tailwind 클래스) */
  height?: string;
  /** 유리 카드 컨테이너에 추가할 CSS 클래스입니다. */
  className?: string;
  /** 유리 카드 내부에 표시할 React 콘텐츠입니다. */
  children?: ReactNode;
}

function hexToRgb(hex: string): { r: number; g: number; b: number } {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return result
    ? {
        r: parseInt(result[1], 16),
        g: parseInt(result[2], 16),
        b: parseInt(result[3], 16),
      }
    : { r: 255, g: 255, b: 255 };
}

export default function GlassmorphismCard({
  blurAmount = 16,
  bgOpacity = 0.08,
  bgColor = "#ffffff",
  enableReflection = true,
  reflectionSize = 250,
  reflectionOpacity = 0.15,
  enableTilt = true,
  maxTilt = 8,
  edgeHighlight = 0.4,
  noiseOpacity = 0.03,
  innerShadow = 0.3,
  width = "w-80",
  height = "h-52",
  className = "",
  children,
}: GlassmorphismCardProps) {
  const cardRef = useRef<HTMLDivElement>(null);
  const reflectionRef = useRef<HTMLDivElement>(null);
  const specularRef = useRef<HTMLDivElement>(null);
  const rafRef = useRef<number>(0);

  const handleMouseMove = useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      const card = cardRef.current;
      if (!card) return;

      cancelAnimationFrame(rafRef.current);
      rafRef.current = requestAnimationFrame(() => {
        const rect = card.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        const centerX = rect.width / 2;
        const centerY = rect.height / 2;
        const normalX = (x - centerX) / centerX; // -1 ~ 1
        const normalY = (y - centerY) / centerY; // -1 ~ 1

        // 3D tilt
        if (enableTilt) {
          const rotateX = -normalY * maxTilt;
          const rotateY = normalX * maxTilt;
          card.style.transform = `perspective(800px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) scale3d(1.02, 1.02, 1.02)`;
        }

        // Diffuse reflection (큰 부드러운 빛)
        if (enableReflection && reflectionRef.current) {
          reflectionRef.current.style.background = `radial-gradient(${reflectionSize}px circle at ${x}px ${y}px, rgba(255, 255, 255, ${reflectionOpacity}), transparent 70%)`;
          reflectionRef.current.style.opacity = "1";
        }

        // Specular highlight (작고 강한 하이라이트)
        if (enableReflection && specularRef.current) {
          const specSize = reflectionSize * 0.35;
          specularRef.current.style.background = `radial-gradient(${specSize}px circle at ${x}px ${y}px, rgba(255, 255, 255, ${reflectionOpacity * 2}), transparent 50%)`;
          specularRef.current.style.opacity = "1";
        }
      });
    },
    [enableReflection, enableTilt, maxTilt, reflectionSize, reflectionOpacity],
  );

  const handleMouseLeave = useCallback(() => {
    const card = cardRef.current;
    if (card && enableTilt) {
      card.style.transform = "perspective(800px) rotateX(0deg) rotateY(0deg) scale3d(1, 1, 1)";
    }
    if (reflectionRef.current) {
      reflectionRef.current.style.opacity = "0";
    }
    if (specularRef.current) {
      specularRef.current.style.opacity = "0";
    }
  }, [enableTilt]);

  const rgb = hexToRgb(bgColor);

  return (
    <div
      ref={cardRef}
      className={`${width} ${height} relative overflow-hidden rounded-2xl ${className}`}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      style={{
        backdropFilter: `blur(${blurAmount}px) saturate(1.2)`,
        WebkitBackdropFilter: `blur(${blurAmount}px) saturate(1.2)`,
        backgroundColor: `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${bgOpacity})`,
        boxShadow: [
          // 외부 그림자 — 유리가 뜬 느낌
          `0 8px 32px rgba(0, 0, 0, 0.2)`,
          `0 2px 8px rgba(0, 0, 0, 0.1)`,
          // 내부 그림자 — 유리 두께감
          `inset 0 1px 0 rgba(255, 255, 255, ${edgeHighlight})`,
          `inset 0 -1px 0 rgba(0, 0, 0, ${innerShadow * 0.3})`,
          `inset 1px 0 0 rgba(255, 255, 255, ${edgeHighlight * 0.5})`,
          `inset -1px 0 0 rgba(0, 0, 0, ${innerShadow * 0.15})`,
          // 내부 깊은 그림자 — 두께 표현
          `inset 0 4px 12px rgba(0, 0, 0, ${innerShadow * 0.15})`,
          `inset 0 -2px 8px rgba(0, 0, 0, ${innerShadow * 0.1})`,
        ].join(", "),
        transition: "transform 0.2s ease-out, box-shadow 0.2s ease-out",
        transformStyle: "preserve-3d",
        willChange: "transform",
      }}
    >
      {/* 1) Top/Left edge highlight — 방향성 있는 빛 */}
      <div
        className="pointer-events-none absolute inset-0 z-[1] rounded-2xl"
        style={{
          background: `linear-gradient(135deg, rgba(255, 255, 255, ${edgeHighlight * 0.3}) 0%, transparent 40%, transparent 60%, rgba(0, 0, 0, ${edgeHighlight * 0.15}) 100%)`,
        }}
      />

      {/* 2) Border gradient — 위/왼쪽 밝고 아래/오른쪽 어둡게 */}
      <div
        className="pointer-events-none absolute inset-0 z-[2] rounded-2xl"
        style={{
          border: "1px solid transparent",
          borderImage: `linear-gradient(135deg, rgba(255,255,255,${edgeHighlight * 0.8}), rgba(255,255,255,${edgeHighlight * 0.2}) 50%, rgba(255,255,255,${edgeHighlight * 0.05})) 1`,
          WebkitMask: "linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)",
          WebkitMaskComposite: "xor",
          maskComposite: "exclude",
          padding: "1px",
        }}
      />
      {/* 실제 테두리 — 그라디언트 보더 */}
      <div
        className="pointer-events-none absolute inset-0 z-[2] rounded-2xl"
        style={{
          background: `linear-gradient(135deg, rgba(255,255,255,${edgeHighlight * 0.6}), rgba(255,255,255,${edgeHighlight * 0.1}) 50%, rgba(255,255,255,0.02))`,
          WebkitMask: "linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)",
          WebkitMaskComposite: "xor",
          maskComposite: "exclude",
          padding: "1px",
          borderRadius: "1rem",
        }}
      />

      {/* 3) Surface noise — 유리 표면 미세 불규칙 */}
      {noiseOpacity > 0 && (
        <svg
          className="pointer-events-none absolute inset-0 z-[3] h-full w-full rounded-2xl"
          style={{ opacity: noiseOpacity }}
        >
          <filter id="glass-noise">
            <feTurbulence type="fractalNoise" baseFrequency="0.8" numOctaves="4" stitchTiles="stitch" />
            <feColorMatrix type="saturate" values="0" />
          </filter>
          <rect width="100%" height="100%" filter="url(#glass-noise)" />
        </svg>
      )}

      {/* 4) Diffuse reflection — 큰 부드러운 반사 */}
      {enableReflection && (
        <div
          ref={reflectionRef}
          className="pointer-events-none absolute inset-0 z-[4] rounded-2xl"
          style={{
            opacity: 0,
            transition: "opacity 0.4s ease-out",
            mixBlendMode: "soft-light",
          }}
        />
      )}

      {/* 5) Specular highlight — 작고 강한 하이라이트 */}
      {enableReflection && (
        <div
          ref={specularRef}
          className="pointer-events-none absolute inset-0 z-[5] rounded-2xl"
          style={{
            opacity: 0,
            transition: "opacity 0.3s ease-out",
            mixBlendMode: "overlay",
          }}
        />
      )}

      {/* 6) Bottom frosted edge — 아래쪽 서리 효과 */}
      <div
        className="pointer-events-none absolute bottom-0 left-0 right-0 z-[6] h-1/3 rounded-b-2xl"
        style={{
          background: `linear-gradient(to top, rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${bgOpacity * 1.5}), transparent)`,
        }}
      />

      {/* Content */}
      <div className="relative z-[10] h-full w-full p-6">{children}</div>
    </div>
  );
}
